#!/usr/bin/env python3
"""Composes player_frames.txt from shared body parts.

Each frame stacks parts (legs, torso, head, arms, paddle) at pixel offsets,
so the head and torso stay identical across poses and only the limbs are
redrawn. Keys are palette contract v2 roles (see player_frames.txt header).

    python3 art/sprites/src/compose.py
"""
from pathlib import Path

HERE = Path(__file__).resolve().parent
W = H = 32
FOOT_ROW = 29

HEADER = """\
# GENERATED by compose.py from body parts; edit compose.py, not this file.
# Player body frames, 32x32, facing right, feet end on row 29.
# Keys -> palette contract v2 (ADR-013):
#  . 0 transparent   o 1 outline     a b c 2-4 skin dark/mid/light
#  D M L 5-7 shirt/cap dark/mid/light   q w 8-9 shorts shadow/white
#  x 10 shoe accent  p P e 11-13 paddle face dark/light, edge-grip
#  h 14 highlight    r 15 hair
"""


def part(text):
    return text.strip("\n").split("\n")


def rot_cw(rows):
    w = max(len(r) for r in rows)
    rows = [r.ljust(w, ".") for r in rows]
    return ["".join(rows[len(rows) - 1 - y][x] for y in range(len(rows)))
            for x in range(w)]


def flip_h(rows):
    w = max(len(r) for r in rows)
    return [r.ljust(w, ".")[::-1] for r in rows]


